 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    seen = set()
    rects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r,c) in seen:
                continue
            q = deque([(r,c)])
            seen.add((r,c))
            cells = []
            while q:
                y,x = q.popleft(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and grid[ny][nx]==color:
                        seen.add((ny,nx)); q.append((ny,nx))
            r0=min(y for y,x in cells); r1=max(y for y,x in cells)
            c0=min(x for y,x in cells); c1=max(x for y,x in cells)
            area=(r1-r0+1)*(c1-c0+1)
            if area >= 8 and len(cells)/area >= 0.55:
                rects.append((r0,r1,c0,c1,color))
    out=[[bg]*w for _ in range(h)]
    for r0,r1,c0,c1,color in rects:
        for r in range(r0,r1+1):
            for c in range(c0,c1+1): out[r][c]=color
    return out
